INSERT INTO `text` VALUES (10, '坡上立着一只鹅，坡下就是一条河。宽宽的河，肥肥的鹅，鹅要过河，河要渡鹅不知是鹅过河，还是河渡鹅', 21);
INSERT INTO `text` VALUES (11, '山上五棵树，架上五壶醋，林中五只鹿，箱里五条裤。伐了山上树，搬下架上的醋，射死林中的鹿，取出箱中的裤。', 21);
INSERT INTO `text` VALUES (12, '扁担长，板凳宽，扁担没有板凳宽，板凳没有扁担长。扁担绑在板凳上，板凳不让扁担绑在板凳上。', 22);
INSERT INTO `text` VALUES (13, '山前有个严圆眼，山后有个严眼圆，二人山前来比眼，不知是严圆眼的眼圆，还是严眼圆比严圆眼的眼圆?', 22);
INSERT INTO `text` VALUES (14, '出南门，走六步，见着六叔和六舅，叫声六叔和六舅，借我六斗六升好绿豆;过了秋，打了豆，还我六叔六舅六十六斗六升好绿豆', 23);
INSERT INTO `text` VALUES (15, '哥挎瓜筐过宽沟，过沟筐漏瓜滚沟。隔沟挎筐瓜筐扣，瓜滚筐空哥怪沟', 23);
INSERT INTO `text` VALUES (16, '老方扛着黄幌子，老黄扛着方幌子。老方要拿老黄的方幌子，老黄要拿老方的黄幌子，末了儿方幌子碰破了黄幌子，黄幌子碰破了方幌子', 24);
INSERT INTO `text` VALUES (17, '粉红墙上画凤凰，红凤凰，粉凤凰，粉红凤凰，花凤凰', 24);
INSERT INTO `text` VALUES (18, '你会炖炖冻豆腐，你来炖我的炖冻豆腐;你不会炖炖冻豆腐，别胡炖乱炖炖坏了我的炖冻豆腐。', 25);
INSERT INTO `text` VALUES (19, '老罗拉了一车梨，老李拉了一车栗。老罗人称大力罗，老李人称李大力。老罗拉梨做梨\n酒，老李拉栗去换梨。', 25);
INSERT INTO `text` VALUES (20, '一班有个黄贺，二班有个王克，黄贺、王克二人搞创作，黄贺搞木刻，王克写诗歌。黄贺帮助王克写诗歌，王克帮助黄贺搞木刻。由于二人搞协作，黄贺完成了木刻，王克写好了诗歌', 26);
INSERT INTO `text` VALUES (21, '小郭画了朵红花，小葛画了朵黄花，小郭想拿他的红花换小葛的黄花，小葛把他的黄花换了小郭的红花。', 26);
